use crate::aap::caps::{http_client, state_read};

const HEX: &[u8; 16] = b"0123456789ABCDEF";

/// Percent-encode a string for use as a query-parameter value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment side call, one per input item. The response is deliberately
        // discarded so the node's output is unaffected by it. `fetch` returns
        // transport failures as values, so a down enrichment service does not
        // fail the node.
        for item in &items {
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                encode_query(&item.text)
            );
            let _ = http_client::fetch(&url);
        }

        // DropSeen: keep only items whose id is not already in the 'seen' store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
